import{_ as e,o as t,c as o,a2 as i}from"./chunks/framework.C0KMm31j.js";const r="/Nav2ArticlesSite/article-assets/2026-07-21/nav2_rotation_shim_01_package_boundary.png",l="/Nav2ArticlesSite/article-assets/2026-07-21/nav2_rotation_shim_02_lifecycle_nested.png",n="/Nav2ArticlesSite/article-assets/2026-07-21/nav2_rotation_shim_03_compute_state_machine.png",c="/Nav2ArticlesSite/article-assets/2026-07-21/nav2_rotation_shim_04_path_alignment.png",s="/Nav2ArticlesSite/article-assets/2026-07-21/nav2_rotation_shim_05_rotation_collision.png",h="/Nav2ArticlesSite/article-assets/2026-07-21/nav2_rotation_shim_06_results_parameters.png",g=JSON.parse('{"title":"别让机器人一上来就“甩尾”：拆解 Nav2 Rotation Shim 的全调用、状态与数据流","description":"全局路径起点方向与机器人车头差得太大时，主控制器可能一边前进一边急转。Rotation Shim 的作用，是在路径跟踪前先把车头对齐，再把控制权交还内部主控制器；它也可以在接近终点后接管最终朝向。","frontmatter":{"title":"别让机器人一上来就“甩尾”：拆解 Nav2 Rotation Shim 的全调用、状态与数据流","description":"全局路径起点方向与机器人车头差得太大时，主控制器可能一边前进一边急转。Rotation Shim 的作用，是在路径跟踪前先把车头对齐，再把控制权交还内部主控制器；它也可以在接近终点后接管最终朝向。","date":"2026-07-21","section":"三 · 局部控制与速度生成","readingTime":6,"source":"2026-07-21/nav2_rotation_shim_controller_full_dataflow.md","status":"published","cover":"/article-assets/2026-07-21/nav2_rotation_shim_01_package_boundary.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-rotation-shim-controller-full-dataflow"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"别让机器人一上来就“甩尾”：拆解 Nav2 Rotation Shim 的全调用、状态与数据流"}],["meta",{"property":"og:description","content":"全局路径起点方向与机器人车头差得太大时，主控制器可能一边前进一边急转。Rotation Shim 的作用，是在路径跟踪前先把车头对齐，再把控制权交还内部主控制器；它也可以在接近终点后接管最终朝向。"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-rotation-shim-controller-full-dataflow"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-21/nav2_rotation_shim_01_package_boundary.png"}],["meta",{"property":"article:published_time","content":"2026-07-21"}],["meta",{"name":"twitter:title","content":"别让机器人一上来就“甩尾”：拆解 Nav2 Rotation Shim 的全调用、状态与数据流"}],["meta",{"name":"twitter:description","content":"全局路径起点方向与机器人车头差得太大时，主控制器可能一边前进一边急转。Rotation Shim 的作用，是在路径跟踪前先把车头对齐，再把控制权交还内部主控制器；它也可以在接近终点后接管最终朝向。"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-21/nav2_rotation_shim_01_package_boundary.png"}]],"prev":{"text":"前方放一根“胡萝卜”，机器人就会转弯？拆解 Nav2 RPP 全调用、状态与数据流","link":"/nav2/nav2-regulated-pure-pursuit-controller-full-dataflow"},"next":{"text":"机器人明明在动，Nav2 为什么还要追问速度？拆解 Odometry 如何驱动控制闭环","link":"/nav2/nav2-controller-odometry-velocity-flow"}},"headers":[],"relativePath":"nav2/nav2-rotation-shim-controller-full-dataflow.md","filePath":"nav2/nav2-rotation-shim-controller-full-dataflow.md","lastUpdated":null}'),d={name:"nav2/nav2-rotation-shim-controller-full-dataflow.md"};function p(_,a,m,u,b,f){return t(),o("div",null,[...a[0]||(a[0]=[i('<h1 id="别让机器人一上来就-甩尾-拆解-nav2-rotation-shim-的全调用、状态与数据流" tabindex="-1">别让机器人一上来就“甩尾”：拆解 Nav2 Rotation Shim 的全调用、状态与数据流 <a class="header-anchor" href="#别让机器人一上来就-甩尾-拆解-nav2-rotation-shim-的全调用、状态与数据流" aria-label="Permalink to &quot;别让机器人一上来就“甩尾”：拆解 Nav2 Rotation Shim 的全调用、状态与数据流&quot;">​</a></h1><p>全局路径起点方向与机器人车头差得太大时，主控制器可能一边前进一边急转。Rotation Shim 的作用，是在路径跟踪前先把车头对齐，再把控制权交还内部主控制器；它也可以在接近终点后接管最终朝向。</p><h2 id="一、它是-controller-外面的-shim" tabindex="-1">一、它是 Controller 外面的 Shim <a class="header-anchor" href="#一、它是-controller-外面的-shim" aria-label="Permalink to &quot;一、它是 Controller 外面的 Shim&quot;">​</a></h2><h3 id="_1-1-本包不创建-ros-2-节点" tabindex="-1">1.1 本包不创建 ROS 2 节点 <a class="header-anchor" href="#_1-1-本包不创建-ros-2-节点" aria-label="Permalink to &quot;1.1 本包不创建 ROS 2 节点&quot;">​</a></h3><p><code>RotationShimController</code> 实现 <code>nav2_core::Controller</code>，由 Controller Server 通过 pluginlib 加载。FollowPath Action、Path、Odometry、Local Costmap、TF、GoalChecker、speed limit 和最终 <code>cmd_vel</code> 都由服务器管理。</p><p>Shim 收到 <code>setPlan()</code> 与 <code>computeVelocityCommands()</code> 调用，返回 <code>TwistStamped</code>，不直接持有外部 Action 或速度 Publisher。</p><h3 id="_1-2-内部再加载一个主控制器" tabindex="-1">1.2 内部再加载一个主控制器 <a class="header-anchor" href="#_1-2-内部再加载一个主控制器" aria-label="Permalink to &quot;1.2 内部再加载一个主控制器&quot;">​</a></h3><p>configure 阶段，Shim 根据 <code>primary_controller</code> 类型创建 DWB、RPP 或其他 Controller，并把同一父 Lifecycle Node、插件 ID、TF 和 Costmap 继续传入。外层只负责旋转接管，正常路径跟踪仍由内部插件完成。</p><p><img src="'+r+'" alt="Rotation Shim 包边界与嵌套控制器"></p><h2 id="二、lifecycle-怎样驱动两层插件" tabindex="-1">二、Lifecycle 怎样驱动两层插件 <a class="header-anchor" href="#二、lifecycle-怎样驱动两层插件" aria-label="Permalink to &quot;二、Lifecycle 怎样驱动两层插件&quot;">​</a></h2><h3 id="_2-1-configure-建立共享环境" tabindex="-1">2.1 configure 建立共享环境 <a class="header-anchor" href="#_2-1-configure-建立共享环境" aria-label="Permalink to &quot;2.1 configure 建立共享环境&quot;">​</a></h3><p>外层读取角阈值、采样距离、角速度、角加速度、碰撞预测时长和闭环模式，创建 PositionGoalChecker、FootprintCollisionChecker 与内部主控制器。</p><h3 id="_2-2-运行状态同步转发" tabindex="-1">2.2 运行状态同步转发 <a class="header-anchor" href="#_2-2-运行状态同步转发" aria-label="Permalink to &quot;2.2 运行状态同步转发&quot;">​</a></h3><p><code>activate()</code>、<code>deactivate()</code>、<code>cleanup()</code> 会同步调用内部 Controller。外层不是独立 Lifecycle Node，却必须保证内部插件与 Controller Server 的状态一致，否则 Publisher、参数回调和资源释放会失配。</p><p><img src="'+l+'" alt="外层 Shim 与内部 Controller 的 Lifecycle"></p><h2 id="三、三个状态变量决定控制权" tabindex="-1">三、三个状态变量决定控制权 <a class="header-anchor" href="#三、三个状态变量决定控制权" aria-label="Permalink to &quot;三、三个状态变量决定控制权&quot;">​</a></h2><h3 id="_3-1-path-updated" tabindex="-1">3.1 path_updated_ <a class="header-anchor" href="#_3-1-path-updated" aria-label="Permalink to &quot;3.1 path_updated_&quot;">​</a></h3><p>新 Path 到来后置位，表示下一控制周期需要判断初始航向。完成判断后清除，避免每帧重复触发。</p><h3 id="_3-2-in-rotation" tabindex="-1">3.2 in_rotation_ <a class="header-anchor" href="#_3-2-in-rotation" aria-label="Permalink to &quot;3.2 in_rotation_&quot;">​</a></h3><p>记录初始对齐是否已进入旋转阶段。未进入时使用触发阈值，进入后使用更小的退出阈值，形成迟滞，避免控制权在 Shim 与主控制器之间抖动。</p><h3 id="_3-3-last-angular-vel" tabindex="-1">3.3 last_angular_vel_ <a class="header-anchor" href="#_3-3-last-angular-vel" aria-label="Permalink to &quot;3.3 last_angular_vel_&quot;">​</a></h3><p>开环旋转时保存上一帧命令角速度，作为下一周期加速度限制的起点。闭环模式则改用 Odometry 的 <code>angular.z</code>。</p><h2 id="四、computevelocitycommands-的优先级" tabindex="-1">四、computeVelocityCommands 的优先级 <a class="header-anchor" href="#四、computevelocitycommands-的优先级" aria-label="Permalink to &quot;四、computeVelocityCommands 的优先级&quot;">​</a></h2><h3 id="_4-1-目标末端旋转" tabindex="-1">4.1 目标末端旋转 <a class="header-anchor" href="#_4-1-目标末端旋转" aria-label="Permalink to &quot;4.1 目标末端旋转&quot;">​</a></h3><p>开启 <code>rotate_to_goal_heading</code> 后，Shim 先检查机器人是否进入 Path 终点 XY 容差。若位置已到达但 yaw 未对齐，Shim 直接生成原地旋转命令。</p><h3 id="_4-2-新路径初始对齐" tabindex="-1">4.2 新路径初始对齐 <a class="header-anchor" href="#_4-2-新路径初始对齐" aria-label="Permalink to &quot;4.2 新路径初始对齐&quot;">​</a></h3><p>若有新 Path，Shim 计算机器人视角下的路径初始方向。误差超过阈值时进入旋转；误差小于退出阈值时结束接管。</p><h3 id="_4-3-主控制器兜底" tabindex="-1">4.3 主控制器兜底 <a class="header-anchor" href="#_4-3-主控制器兜底" aria-label="Permalink to &quot;4.3 主控制器兜底&quot;">​</a></h3><p>不需要旋转时，Pose、Odometry Twist 和 GoalChecker 原样传给内部主控制器。三条分支最终都返回相同的 <code>TwistStamped</code> 接口。</p><p><img src="'+n+'" alt="Rotation Shim 控制权状态机"></p><h2 id="五、新路径方向怎样计算" tabindex="-1">五、新路径方向怎样计算 <a class="header-anchor" href="#五、新路径方向怎样计算" aria-label="Permalink to &quot;五、新路径方向怎样计算&quot;">​</a></h2><h3 id="_5-1-采样点不能离起点太近" tabindex="-1">5.1 采样点不能离起点太近 <a class="header-anchor" href="#_5-1-采样点不能离起点太近" aria-label="Permalink to &quot;5.1 采样点不能离起点太近&quot;">​</a></h3><p>算法从 Path 首 Pose 开始，向后寻找直线位移达到 <code>forward_sampling_distance</code> 的首个点。距离过短会被离散噪声或局部曲线放大，距离过长又可能忽略近处急转。</p><h3 id="_5-2-方向必须进入-base-frame" tabindex="-1">5.2 方向必须进入 base frame <a class="header-anchor" href="#_5-2-方向必须进入-base-frame" aria-label="Permalink to &quot;5.2 方向必须进入 base frame&quot;">​</a></h3><p>采样点刷新时间戳后，通过 TF 变换到机器人 base frame，再用 <code>atan2(y, x)</code> 得到路径相对车头方向。TF 失败或 Path 太短时，Shim 可回退内部主控制器，而不是盲目旋转。</p><p><img src="'+c+`" alt="新路径初始航向采样"></p><h2 id="六、旋转速度如何生成" tabindex="-1">六、旋转速度如何生成 <a class="header-anchor" href="#六、旋转速度如何生成" aria-label="Permalink to &quot;六、旋转速度如何生成&quot;">​</a></h2><h3 id="_6-1-方向来自航向误差符号" tabindex="-1">6.1 方向来自航向误差符号 <a class="header-anchor" href="#_6-1-方向来自航向误差符号" aria-label="Permalink to &quot;6.1 方向来自航向误差符号&quot;">​</a></h3><p>目标角速度为 <code>±rotate_to_heading_angular_vel</code>，线速度固定为零。控制周期 <code>dt</code> 来自 <code>1/controller_frequency</code>。</p><h3 id="_6-2-当前速度决定单周期可达范围" tabindex="-1">6.2 当前速度决定单周期可达范围 <a class="header-anchor" href="#_6-2-当前速度决定单周期可达范围" aria-label="Permalink to &quot;6.2 当前速度决定单周期可达范围&quot;">​</a></h3><p>闭环时使用 Odometry 角速度，开环时使用 <code>last_angular_vel_</code>。输出被夹紧到：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[current_wz - max_angular_accel × dt,</span></span>
<span class="line"><span> current_wz + max_angular_accel × dt]</span></span></code></pre></div><p>本地实现没有像 RPP 那样按剩余角度计算主动制动上限，因此终点角度、角速度和退出阈值需要联合验证。</p><h3 id="_6-3-原地旋转仍需碰撞预测" tabindex="-1">6.3 原地旋转仍需碰撞预测 <a class="header-anchor" href="#_6-3-原地旋转仍需碰撞预测" aria-label="Permalink to &quot;6.3 原地旋转仍需碰撞预测&quot;">​</a></h3><p>非圆形 footprint 旋转会扫过更大区域。Shim 在 <code>simulate_ahead_time</code> 内保持 <code>x、y</code> 不变、逐步推进 yaw，每个姿态都查询 Local Costmap footprint 代价。未知或致命代价会拒绝本次旋转。</p><p><img src="`+s+'" alt="旋转速度与 Footprint 碰撞预测"></p><h2 id="七、异常、限速与动态参数" tabindex="-1">七、异常、限速与动态参数 <a class="header-anchor" href="#七、异常、限速与动态参数" aria-label="Permalink to &quot;七、异常、限速与动态参数&quot;">​</a></h2><h3 id="_7-1-shim-异常可以回退" tabindex="-1">7.1 Shim 异常可以回退 <a class="header-anchor" href="#_7-1-shim-异常可以回退" aria-label="Permalink to &quot;7.1 Shim 异常可以回退&quot;">​</a></h3><p>初始路径采样、TF 或旋转碰撞异常可让外层放弃接管并委托内部 Controller。内部 Controller 抛出的 PlannerException 则继续交给 Controller Server，由 <code>failure_tolerance</code> 决定短暂零速还是 FollowPath 失败。</p><h3 id="_7-2-setspeedlimit-只转发内部插件" tabindex="-1">7.2 setSpeedLimit 只转发内部插件 <a class="header-anchor" href="#_7-2-setspeedlimit-只转发内部插件" aria-label="Permalink to &quot;7.2 setSpeedLimit 只转发内部插件&quot;">​</a></h3><p>speed limit 不直接改变 Shim 的 <code>rotate_to_heading_angular_vel</code>，只传给内部主控制器。限速区中仍需单独验证旋转速度是否符合底盘和安全要求。</p><h3 id="_7-3-动态参数存在边界" tabindex="-1">7.3 动态参数存在边界 <a class="header-anchor" href="#_7-3-动态参数存在边界" aria-label="Permalink to &quot;7.3 动态参数存在边界&quot;">​</a></h3><p>本地回调可更新主要角度、速度、加速度、预测时长和部分布尔开关，但不能运行时替换 <code>primary_controller</code>。<code>controller_frequency</code> 改变后也不会自动重算已缓存的 <code>control_duration</code>。</p><p><img src="'+h+`" alt="Rotation Shim 结果与参数边界"></p><h2 id="八、本地版本必须单独核对" tabindex="-1">八、本地版本必须单独核对 <a class="header-anchor" href="#八、本地版本必须单独核对" aria-label="Permalink to &quot;八、本地版本必须单独核对&quot;">​</a></h2><h3 id="_8-1-本文以本地-1-1-20-为准" tabindex="-1">8.1 本文以本地 1.1.20 为准 <a class="header-anchor" href="#_8-1-本文以本地-1-1-20-为准" aria-label="Permalink to &quot;8.1 本文以本地 1.1.20 为准&quot;">​</a></h3><p>当前源码没有最新版文档中的 <code>max_cost_threshold</code>、<code>rotate_to_heading_once</code> 和 <code>use_path_orientations</code>，内部控制器参数结构也不同。不能从 latest 文档复制参数后假设本地实现会读取。</p><h3 id="_8-2-源码审计关注点" tabindex="-1">8.2 源码审计关注点 <a class="header-anchor" href="#_8-2-源码审计关注点" aria-label="Permalink to &quot;8.2 源码审计关注点&quot;">​</a></h3><ul><li>PositionGoalChecker 的初始化顺序值得修正。</li><li>内部插件创建失败没有形成清晰的 configure 失败返回。</li><li>末端旋转的 Costmap 加锁范围与初始旋转不同。</li><li>碰撞模拟提前停止条件对正反转方向不完全对称。</li><li>新 Path 不会显式重置全部 <code>in_rotation_</code> 状态。</li></ul><h2 id="九、配置与排障" tabindex="-1">九、配置与排障 <a class="header-anchor" href="#九、配置与排障" aria-label="Permalink to &quot;九、配置与排障&quot;">​</a></h2><h3 id="_9-1-当前项目使用内部-dwb" tabindex="-1">9.1 当前项目使用内部 DWB <a class="header-anchor" href="#_9-1-当前项目使用内部-dwb" aria-label="Permalink to &quot;9.1 当前项目使用内部 DWB&quot;">​</a></h3><p>当前配置启用初始旋转、<code>closed_loop=true</code>，并把 DWB 作为内部主控制器。调试时应分别观察外层旋转参数与内层 DWB 参数，不能只看一个 controller ID。</p><h3 id="_9-2-按控制权定位" tabindex="-1">9.2 按控制权定位 <a class="header-anchor" href="#_9-2-按控制权定位" aria-label="Permalink to &quot;9.2 按控制权定位&quot;">​</a></h3><ul><li>没进入 Shim：检查 Path 采样、TF 和角阈值。</li><li>进入但不旋转：检查 Odometry <code>wz</code>、加速度窗口与碰撞预测。</li><li>无法退出：检查迟滞阈值和 Path frame。</li><li>交接后失败：进入内部主控制器与 Local Costmap 排查。</li></ul><h2 id="十、总结与参考" tabindex="-1">十、总结与参考 <a class="header-anchor" href="#十、总结与参考" aria-label="Permalink to &quot;十、总结与参考&quot;">​</a></h2><h3 id="_10-1-完整数据主线" tabindex="-1">10.1 完整数据主线 <a class="header-anchor" href="#_10-1-完整数据主线" aria-label="Permalink to &quot;10.1 完整数据主线&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>FollowPath → Controller Server → Rotation Shim</span></span>
<span class="line"><span>→ 末端旋转／初始对齐／内部 Controller</span></span>
<span class="line"><span>→ 限加速度角速度＋碰撞预测</span></span>
<span class="line"><span>→ TwistStamped → Controller Server → cmd_vel</span></span></code></pre></div><p>Rotation Shim 的价值不是“增加一次旋转”，而是把控制权切换、角速度连续性和 footprint 安全检查封装在统一 Controller 接口中。</p><h3 id="_10-2-官方参考" tabindex="-1">10.2 官方参考 <a class="header-anchor" href="#_10-2-官方参考" aria-label="Permalink to &quot;10.2 官方参考&quot;">​</a></h3><p><a href="https://docs.nav2.org/configuration/packages/configuring-rotation-shim-controller.html" target="_blank" rel="noreferrer">Nav2 Rotation Shim Controller 配置</a></p><p><a href="https://github.com/ros-navigation/navigation2/tree/main/nav2_rotation_shim_controller" target="_blank" rel="noreferrer">Navigation2 Rotation Shim 源码</a></p>`,71)])])}const q=e(d,[["render",p]]);export{g as __pageData,q as default};
